'use server'

import { prisma } from "@/lib/prisma";
import { hash } from "bcryptjs";
import { redirect } from "next/navigation";

export async function registerUser(prevState: any, formData: FormData): Promise<{ error?: string }> {
    const name = formData.get("name") as string;
    const email = formData.get("email") as string;
    const password = formData.get("password") as string;

    if (!email || !password || !name) {
        return { error: "Todos os campos são obrigatórios." };
    }

    const existingUser = await prisma.user.findUnique({
        where: { email },
    });

    if (existingUser) {
        return { error: "Email já cadastrado." };
    }

    const hashedPassword = await hash(password, 10);

    await prisma.user.create({
        data: {
            name,
            email,
            password: hashedPassword,
        },
    });

    redirect("/login");
}

'use server'

import { prisma } from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";

export async function createCustomIngredient(prevState: any, formData: FormData): Promise<{ error?: string; success?: boolean }> {
    const session = await getServerSession(authOptions);
    if (!session || !session.user?.email) return { error: "Não autorizado" };

    const user = await prisma.user.findUnique({ where: { email: session.user.email } });
    if (!user) return { error: "Usuário não encontrado" };

    const name = formData.get("name") as string;
    const energy = parseFloat(formData.get("energy") as string) || 0;
    const carbs = parseFloat(formData.get("carbs") as string) || 0;
    const protein = parseFloat(formData.get("protein") as string) || 0;
    const fatTotal = parseFloat(formData.get("fatTotal") as string) || 0;
    const fatSat = parseFloat(formData.get("fatSat") as string) || 0;
    const fatTrans = parseFloat(formData.get("fatTrans") as string) || 0;
    const fiber = parseFloat(formData.get("fiber") as string) || 0;
    const sodium = parseFloat(formData.get("sodium") as string) || 0;
    const sugarTotal = parseFloat(formData.get("sugarTotal") as string) || 0;

    if (!name) return { error: "Nome é obrigatório" };

    try {
        await prisma.customIngredient.create({
            data: {
                userId: user.id,
                name: `[Meu] ${name}`, // Prefix as requested
                energy,
                carbs,
                protein,
                fatTotal,
                fatSat,
                fatTrans,
                fiber,
                sodium,
                sugarTotal
            }
        });

        revalidatePath("/dashboard/ingredients");
        return { success: true };
    } catch (e) {
        return { error: "Erro ao criar ingrediente" };
    }
}

export async function deleteCustomIngredient(id: string) {
    const session = await getServerSession(authOptions);
    if (!session || !session.user?.email) return { error: "Não autorizado" };

    const user = await prisma.user.findUnique({ where: { email: session.user.email } });
    if (!user) return { error: "Usuário não encontrado" };

    try {
        // Ensure ownership
        const ing = await prisma.customIngredient.findUnique({ where: { id } });
        if (!ing || ing.userId !== user.id) return { error: "Não encontrado ou sem permissão" };

        await prisma.customIngredient.delete({ where: { id } });
        revalidatePath("/dashboard/ingredients");
        return { success: true };
    } catch (e) {
        return { error: "Erro ao deletar" };
    }
}

'use server'

import { prisma } from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { hash, compare } from "bcryptjs";
import { revalidatePath } from "next/cache";

export async function changePassword(prevState: any, formData: FormData): Promise<{ error?: string; success?: string }> {
    const session = await getServerSession(authOptions);
    if (!session || !session.user?.email) return { error: "Não autorizado" };

    const currentPassword = formData.get("currentPassword") as string;
    const newPassword = formData.get("newPassword") as string;
    const confirmPassword = formData.get("confirmPassword") as string;

    if (newPassword !== confirmPassword) return { error: "As senhas não coincidem" };
    if (newPassword.length < 6) return { error: "A nova senha deve ter pelo menos 6 caracteres" };

    const user = await prisma.user.findUnique({ where: { email: session.user.email } });
    if (!user) return { error: "Usuário não encontrado" };

    // Verify current
    const isValid = await compare(currentPassword, user.password);
    if (!isValid) return { error: "Senha atual incorreta" };

    const hashedPassword = await hash(newPassword, 10);

    await prisma.user.update({
        where: { id: user.id },
        data: { password: hashedPassword }
    });

    return { success: "Senha alterada com sucesso!" };
}

'use server'

import { prisma } from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { SelectedIngredient } from "@/lib/nutrients";
import { PopGroup } from "@/lib/constants";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";

export async function saveTable(data: {
    id?: string;
    title: string;
    portion: number;
    uom: string;
    householdMeasure: string;
    popGroup: PopGroup;
    ingredients: SelectedIngredient[];
}) {
    const session = await getServerSession(authOptions);

    if (!session || !session.user || !session.user.email) {
        return { error: "Não autorizado" };
    }

    const user = await prisma.user.findUnique({ where: { email: session.user.email } });
    if (!user) return { error: "Usuário não encontrado" };

    try {
        const payload = {
            userId: user.id,
            title: data.title,
            portion: data.portion,
            uom: data.uom,
            householdMeasure: data.householdMeasure,
            popGroup: data.popGroup,
        };

        const itemsPayload = data.ingredients.map(i => ({
            name: i.ingredient.name,
            quantity: i.quantity,
            isAddedSugar: i.isAddedSugar,
            energy: i.ingredient.energy || 0,
            protein: i.ingredient.protein || 0,
            carbs: i.ingredient.carbs || 0,
            fatTotal: i.ingredient.fatTotal || 0,
            fatSat: i.ingredient.fatSat || 0,
            fatTrans: i.ingredient.fatTrans || 0,
            fiber: i.ingredient.fiber || 0,
            sodium: i.ingredient.sodium || 0,
            sugarTotal: i.ingredient.sugarTotal || 0,
        }));

        if (data.id) {
            // Check ownership
            const existing = await prisma.generatedTable.findFirst({
                where: { id: data.id, userId: user.id }
            });

            if (!existing) return { error: "Tabela não encontrada ou permissão negada" };

            // Transaction: Delete old items, update table, create new items
            await prisma.$transaction([
                prisma.tableItem.deleteMany({ where: { tableId: data.id } }),
                prisma.generatedTable.update({
                    where: { id: data.id },
                    data: payload
                }),
                ...itemsPayload.map(item =>
                    prisma.tableItem.create({
                        data: { ...item, tableId: data.id as string }
                    })
                )
            ]);
        } else {
            await prisma.generatedTable.create({
                data: {
                    ...payload,
                    items: {
                        create: itemsPayload
                    }
                }
            });
        }

        revalidatePath("/dashboard");
        revalidatePath(`/dashboard/edit/${data.id}`); // Revalidate edit page
        return { success: true };
    } catch (e) {
        console.error(e);
        return { error: "Erro ao salvar tabela" };
    }
}

