'use client'

import * as React from "react"
import { Check, ChevronsUpDown, Search } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from "@/components/ui/command"
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover"
import { Ingredient } from "@prisma/client"

export function IngredientSelector({ onSelect }: { onSelect: (ing: Ingredient) => void }) {
    const [open, setOpen] = React.useState(false)
    const [value, setValue] = React.useState("")
    const [query, setQuery] = React.useState("")
    const [results, setResults] = React.useState<Ingredient[]>([])
    const [loading, setLoading] = React.useState(false)

    // Debounce search
    React.useEffect(() => {
        const timer = setTimeout(async () => {
            if (query.length < 2) {
                setResults([])
                return
            }
            setLoading(true)
            try {
                const res = await fetch(`/api/ingredients/search?query=${encodeURIComponent(query)}`)
                const data = await res.json()
                setResults(data)
            } catch (e) {
                console.error(e)
            } finally {
                setLoading(false)
            }
        }, 300)

        return () => clearTimeout(timer)
    }, [query])

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                <Button
                    variant="outline"
                    role="combobox"
                    aria-expanded={open}
                    className="w-full justify-between"
                >
                    {value
                        ? results.find((i) => i.id === value)?.name || value
                        : "Buscar ingrediente..."}
                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-[400px] p-0" align="start">
                <Command shouldFilter={false}>
                    <CommandInput
                        placeholder="Digite para buscar..."
                        value={query}
                        onValueChange={setQuery}
                    />
                    <CommandList>
                        {loading && <div className="py-6 text-center text-sm">Buscando...</div>}

                        {!loading && results.length === 0 && (
                            <CommandEmpty>Nenhum ingrediente encontrado.</CommandEmpty>
                        )}

                        <CommandGroup>
                            {results.map((item) => (
                                <CommandItem
                                    key={item.id}
                                    value={item.id} // Shadcn Command uses value to select?
                                    onSelect={() => {
                                        setValue(item.name) // Display name
                                        onSelect(item)
                                        setOpen(false)
                                    }}
                                >
                                    <Check
                                        className={cn(
                                            "mr-2 h-4 w-4",
                                            value === item.id ? "opacity-100" : "opacity-0"
                                        )}
                                    />
                                    {item.name}
                                </CommandItem>
                            ))}
                        </CommandGroup>
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    )
}

import { CalculatedNutrients } from "@/lib/nutrients";
import { calculateVD, roundEnergy, roundMacro, roundSodium, roundSugars, roundSaturatedTrans } from "@/lib/anvisa";
import { VDR, PopGroup, POPULATION_LABELS } from "@/lib/constants";
import { cn } from "@/lib/utils";

const Row = ({ label, val100, valPortion, vd, sub = false, bold = false }: { label: string, val100: string, valPortion: string, vd: string, sub?: boolean, bold?: boolean }) => (
    <div className={cn("flex justify-between border-b py-1 text-sm", sub && "pl-4")} style={{ borderColor: '#d1d5db', backgroundColor: '#ffffff' }}>
        <span className={cn(bold && "font-bold")}>{label}</span>
        <div className="flex gap-4 min-w-[140px] justify-end" style={{ backgroundColor: '#ffffff' }}>
            <span className="w-12 text-right">{val100}</span>
            <span className="w-12 text-right">{valPortion}</span>
            <span className="w-8 text-right font-bold ml-2">{vd}</span>
        </div>
    </div>
);

interface NutritionalLabelProps {
    per100g: CalculatedNutrients;
    perPortion: CalculatedNutrients;
    portionSize: number; // g
    householdMeasure: string;
    popGroup: PopGroup;
}

export function NutritionalLabel({
    per100g,
    perPortion,
    portionSize,
    householdMeasure,
    popGroup,
}: NutritionalLabelProps) {
    const vdr = VDR[popGroup];

    const getVD = (val: number, ref: number | null) => calculateVD(val, ref);

    return (
        <div className="p-4 border-2 max-w-md font-sans" id="nutrition-label-container" style={{ backgroundColor: '#ffffff', borderColor: '#000000', color: '#000000' }}>
            <h2 className="text-xl font-bold border-b-4 pb-1" style={{ borderColor: '#000000' }}>INFORMAÇÃO NUTRICIONAL</h2>
            <div className="text-sm mb-2">
                <p>Porção de {portionSize}g ({householdMeasure})</p>
            </div>

            <div className="border-t-2" style={{ borderColor: '#000000' }}>
                <div className="flex justify-between font-bold text-xs border-b py-1" style={{ backgroundColor: '#f3f4f6', borderColor: '#000000' }}>
                    <span></span>
                    <div className="flex gap-4 min-w-[140px] justify-end">
                        <span className="w-12 text-right">100g</span>
                        <span className="w-12 text-right">Porção</span>
                        <span className="w-8 text-right">%VD*</span>
                    </div>
                </div>

                <Row
                    label="Valor energético (kcal)"
                    val100={roundEnergy(per100g.energy)}
                    valPortion={roundEnergy(perPortion.energy)}
                    vd={getVD(perPortion.energy, vdr.energy)}
                    bold
                />

                <Row
                    label="Carboidratos totais (g)"
                    val100={roundMacro(per100g.carbs)}
                    valPortion={roundMacro(perPortion.carbs)}
                    vd={getVD(perPortion.carbs, vdr.carbs)}
                    bold
                />
                <Row
                    label="Açúcares totais (g)"
                    val100={roundSugars(per100g.sugarTotal)}
                    valPortion={roundSugars(perPortion.sugarTotal)}
                    vd="-" sub
                />
                <Row
                    label="Açúcares adicion. (g)"
                    val100={roundSugars(per100g.sugarAdded)}
                    valPortion={roundSugars(perPortion.sugarAdded)}
                    vd="-" sub
                />

                <Row
                    label="Proteínas (g)"
                    val100={roundMacro(per100g.protein)}
                    valPortion={roundMacro(perPortion.protein)}
                    vd={getVD(perPortion.protein, vdr.protein)}
                    bold
                />

                <Row
                    label="Gorduras totais (g)"
                    val100={roundMacro(per100g.fatTotal)}
                    valPortion={roundMacro(perPortion.fatTotal)}
                    vd={getVD(perPortion.fatTotal, vdr.fatTotal)}
                    bold
                />
                <Row
                    label="Gorduras saturadas (g)"
                    val100={roundSaturatedTrans(per100g.fatSat)}
                    valPortion={roundSaturatedTrans(perPortion.fatSat)}
                    vd={getVD(perPortion.fatSat, vdr.fatSat)}
                    sub
                />
                <Row
                    label="Gorduras trans (g)"
                    val100={roundSaturatedTrans(per100g.fatTrans)}
                    valPortion={roundSaturatedTrans(perPortion.fatTrans)}
                    vd="-" sub
                />

                <Row
                    label="Fibra alimentar (g)"
                    val100={roundMacro(per100g.fiber)}
                    valPortion={roundMacro(perPortion.fiber)}
                    vd={getVD(perPortion.fiber, vdr.fiber)}
                    bold
                />

                <Row
                    label="Sódio (mg)"
                    val100={roundSodium(per100g.sodium)}
                    valPortion={roundSodium(perPortion.sodium)}
                    vd={getVD(perPortion.sodium, vdr.sodium)}
                    bold
                />

            </div>
            <div className="text-xs mt-2 border-t pt-1" style={{ borderColor: '#000000' }}>
                *Percentual de valores diários fornecidos pela porção.
                {vdr.fatSat === null && " (Gorduras saturadas: VDR não estabelecido para este grupo)."}
            </div>
        </div>
    );
}

'use client'

import React, { useState, useEffect } from "react";
import { IngredientSelector } from "./IngredientSelector";
import { SelectedIngredient, calculateRecipe, CalculatedNutrients } from "@/lib/nutrients";
import { NutritionalLabel } from "./NutritionalLabel";
import { MagnifyingGlassLabel } from "./MagnifyingGlassLabel";
import { POPULATION_GROUPS, PopGroup, POPULATION_LABELS } from "@/lib/constants";
import { checkFOP } from "@/lib/anvisa";
import { Ingredient } from "@prisma/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Trash2, Download, Save } from "lucide-react";
import { saveTable } from "@/app/actions/table";
import { toast } from "sonner";
import html2canvas from "html2canvas";

interface TableGeneratorProps {
    initialData?: {
        id: string;
        title: string;
        portionSize: number;
        householdMeasure: string;
        popGroup: string;
        ingredients: SelectedIngredient[];
    };
}

export function TableGenerator({ initialData }: TableGeneratorProps) {
    const [title, setTitle] = useState(initialData?.title || "");
    const [ingredients, setIngredients] = useState<SelectedIngredient[]>(initialData?.ingredients || []);
    const [portionSize, setPortionSize] = useState<number>(initialData?.portionSize || 0);
    const [householdMeasure, setHouseholdMeasure] = useState(initialData?.householdMeasure || "");
    const [popGroup, setPopGroup] = useState<PopGroup>((initialData?.popGroup as PopGroup) || POPULATION_GROUPS.ADULTS);
    const [isSupplement, setIsSupplement] = useState(false);
    const [saving, setSaving] = useState(false);

    const [result, setResult] = useState<{
        per100g: CalculatedNutrients;
        perPortion: CalculatedNutrients;
    } | null>(null);

    const handleAddIngredient = (ing: Ingredient) => {
        setIngredients(prev => [...prev, { ingredient: ing, quantity: 0, isAddedSugar: false }]);
    };

    const updateIngredient = (index: number, field: keyof SelectedIngredient, val: any) => {
        setIngredients(prev => {
            const draft = [...prev];
            draft[index] = { ...draft[index], [field]: val };
            return draft;
        });
    };

    const removeIngredient = (index: number) => {
        setIngredients(prev => prev.filter((_, i) => i !== index));
    };

    useEffect(() => {
        if (ingredients.length > 0 && portionSize > 0) {
            const calc = calculateRecipe(ingredients, portionSize);
            setResult(calc);
        } else {
            setResult(null);
        }
    }, [ingredients, portionSize]);

    const handleSave = async () => {
        if (!title) {
            toast.error("Defina um título para a tabela.");
            return;
        }
        if (!result) {
            toast.error("A tabela ainda não foi gerada (adicione ingredientes e porção).");
            return;
        }

        setSaving(true);
        const res = await saveTable({
            id: initialData?.id,
            title,
            portion: portionSize,
            uom: "g",
            householdMeasure,
            popGroup,
            ingredients
        });
        setSaving(false);

        if (res.error) {
            console.error("Erro no saveTable:", res.error);
            toast.error(`Erro ao salvar: ${res.error}`);
        } else {
            toast.success("Tabela salva com sucesso!");
        }
    };

    const fixColorsOnClone = (clonedDoc: Document) => {
        const style = clonedDoc.createElement('style');
        style.innerHTML = `
            :root {
                --background: #ffffff !important;
                --foreground: #000000 !important;
                --card: #ffffff !important;
                --card-foreground: #000000 !important;
                --popover: #ffffff !important;
                --popover-foreground: #000000 !important;
                --primary: #000000 !important;
                --primary-foreground: #ffffff !important;
                --secondary: #f3f4f6 !important;
                --secondary-foreground: #111827 !important;
                --muted: #f3f4f6 !important;
                --muted-foreground: #6b7280 !important;
                --accent: #f3f4f6 !important;
                --accent-foreground: #111827 !important;
                --destructive: #ef4444 !important;
                --border: #e5e7eb !important;
                --input: #e5e7eb !important;
                --ring: #000000 !important;
            }
            .bg-white { background-color: #ffffff !important; }
            .bg-gray-100 { background-color: #f3f4f6 !important; }
            .border-black { border-color: #000000 !important; }
            .text-black { color: #000000 !important; }
        `;
        clonedDoc.head.appendChild(style);
    };

    const handleExportPNG = async () => {
        const element = document.getElementById("nutrition-label-container");
        if (!element) {
            toast.error("Elemento da tabela não encontrado para exportação.");
            return;
        }

        try {
            const canvas = await html2canvas(element, {
                scale: 3,
                useCORS: true,
                logging: false,
                backgroundColor: "#ffffff",
                onclone: fixColorsOnClone
            } as any);

            const dataUrl = canvas.toDataURL("image/png");
            const link = document.createElement("a");
            link.download = `tabela-${title.replace(/\s+/g, '-') || 'anvisa'}.png`;
            link.href = dataUrl;
            document.body.appendChild(link); // Append to body to ensure click works in some browsers
            link.click();
            document.body.removeChild(link);
            toast.success("Imagem exportada com sucesso!");
        } catch (e) {
            console.error("Erro exportação PNG:", e);
            toast.error("Erro ao gerar imagem. Verifique o console.");
        }
    };



    const exportLupaElement = async (elementId: string, suffix: string) => {
        const element = document.getElementById(elementId);
        if (!element) return;

        try {
            const canvas = await html2canvas(element, {
                scale: 4,
                useCORS: true,
                logging: false,
                backgroundColor: null, // Transparent background
                onclone: fixColorsOnClone
            } as any);

            const dataUrl = canvas.toDataURL("image/png");
            const link = document.createElement("a");
            link.download = `lupa-${suffix}-${title.replace(/\s+/g, '-') || 'anvisa'}.png`;
            link.href = dataUrl;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            toast.success(`Lupa (${suffix}) exportada!`);
        } catch (e) {
            console.error("Erro exportação Lupa:", e);
            toast.error("Erro ao gerar lupa.");
        }
    };

    const handleExportExcel = async () => {
        if (!result) return;
        try {
            const response = await fetch("/api/export/excel", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    title,
                    per100g: result.per100g,
                    perPortion: result.perPortion,
                    portionSize,
                    householdMeasure,
                    popGroup,
                    isSupplement
                })
            });

            if (!response.ok) throw new Error("Falha na exportação");

            const blob = await response.blob();
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = `tabela-${title.replace(/\s+/g, '-')}.xlsx`;
            document.body.appendChild(a);
            a.click();
            window.URL.revokeObjectURL(url);
            document.body.removeChild(a);
            toast.success("Planilha Excel gerada com sucesso!");
        } catch (error) {
            console.error(error);
            toast.error("Erro ao gerar Excel.");
        }
    };

    return (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pb-20">
            <div className="space-y-6">
                <Card>
                    <CardHeader>
                        <CardTitle>Configurações da Receita</CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <div className="space-y-2">
                            <Label>Nome do Produto / Título</Label>
                            <Input
                                value={title}
                                onChange={e => setTitle(e.target.value)}
                                placeholder="ex: Bolo de Cenoura"
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <Label>Porção (g)</Label>
                                <Input
                                    type="number"
                                    value={portionSize || ''}
                                    onChange={e => setPortionSize(parseFloat(e.target.value) || 0)}
                                    placeholder="ex: 20"
                                />
                            </div>
                            <div className="space-y-2">
                                <Label>Medida Caseira</Label>
                                <Input
                                    value={householdMeasure}
                                    onChange={e => setHouseholdMeasure(e.target.value)}
                                    placeholder="ex: 2 colheres"
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <div className="flex items-center justify-between">
                                <Label>Grupo Populacional</Label>
                                <div className="flex items-center space-x-2">
                                    <Checkbox
                                        id="is-supplement"
                                        checked={isSupplement}
                                        onCheckedChange={(c) => setIsSupplement(!!c)}
                                    />
                                    <label
                                        htmlFor="is-supplement"
                                        className="text-sm font-medium leading-none cursor-pointer"
                                    >
                                        Suplemento Alimentar
                                    </label>
                                </div>
                            </div>
                            <Select value={popGroup} onValueChange={(v) => setPopGroup(v as PopGroup)}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Selecione" />
                                </SelectTrigger>
                                <SelectContent>
                                    {Object.entries(POPULATION_LABELS).map(([key, label]) => (
                                        <SelectItem key={key} value={key}>{label}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader>
                        <CardTitle>Ingredientes</CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <IngredientSelector onSelect={handleAddIngredient} />

                        <div className="space-y-2">
                            {ingredients.map((item, idx) => (
                                <div key={idx} className="flex items-end gap-3 p-3 border rounded-md bg-card">
                                    <div className="flex-1 space-y-1">
                                        <div className="font-medium text-sm">{item.ingredient.name}</div>
                                        <div className="flex items-center gap-2">
                                            <div className="w-24">
                                                <Input
                                                    type="number"
                                                    placeholder="Qtd (g)"
                                                    value={item.quantity || ''}
                                                    onChange={e => updateIngredient(idx, 'quantity', parseFloat(e.target.value) || 0)}
                                                    className="h-8"
                                                />
                                            </div>
                                            <div className="flex items-center space-x-2">
                                                <Checkbox
                                                    id={`added-sugar-${idx}`}
                                                    checked={item.isAddedSugar}
                                                    onCheckedChange={(c) => updateIngredient(idx, 'isAddedSugar', !!c)}
                                                />
                                                <label
                                                    htmlFor={`added-sugar-${idx}`}
                                                    className="text-xs font-medium leading-none cursor-pointer"
                                                >
                                                    É açúcar adicionado
                                                </label>
                                            </div>
                                        </div>
                                    </div>
                                    <Button variant="ghost" size="icon" onClick={() => removeIngredient(idx)} className="text-red-500 hover:text-red-700">
                                        <Trash2 className="h-4 w-4" />
                                    </Button>
                                </div>
                            ))}
                            {ingredients.length === 0 && (
                                <div className="text-center text-sm text-muted-foreground py-4 border-2 border-dashed rounded-md">
                                    Adicione ingredientes para começar.
                                </div>
                            )}
                        </div>
                        {ingredients.length > 0 && (
                            <div className="mt-4 pt-4 border-t flex justify-between items-center bg-muted/50 p-4 rounded-md">
                                <span className="font-semibold text-sm">Peso Total dos Ingredientes:</span>
                                <span className="font-bold text-lg text-primary">{ingredients.reduce((acc, item) => acc + (item.quantity || 0), 0).toFixed(1)} g</span>
                            </div>
                        )}
                    </CardContent>
                </Card>
            </div>

            <div className="space-y-6">
                <Card className="sticky top-6">
                    <CardHeader>
                        <CardTitle>Pré-visualização</CardTitle>
                    </CardHeader>
                    <CardContent className="flex flex-col items-center bg-gray-50 py-8 min-h-[400px] gap-8">
                        {result ? (
                            <>
                                <NutritionalLabel
                                    per100g={result.per100g}
                                    perPortion={result.perPortion}
                                    portionSize={portionSize}
                                    householdMeasure={householdMeasure || "..."}
                                    popGroup={popGroup}
                                />
                                <div className="flex flex-col items-center gap-4 w-full">
                                    <div className="text-sm font-semibold text-gray-500 w-full text-center border-t pt-4">Modelos de Lupa (ANVISA)</div>

                                    <div className="flex flex-wrap justify-center gap-8 items-end">
                                        <div className="flex flex-col items-center gap-2">
                                            <div className="flex items-center gap-2">
                                                <div
                                                    id="wrapper-lupa-horizontal"
                                                    className="border-[4px] rounded-[10px] p-[2px] inline-block leading-none"
                                                    style={{ borderColor: '#000000', backgroundColor: '#ffffff' }}
                                                >
                                                    <MagnifyingGlassLabel
                                                        {...checkFOP(result.per100g)}
                                                        layout="horizontal"
                                                        id="lupa-horizontal"
                                                    />
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </>
                        ) : (
                            <div className="text-muted-foreground text-center max-w-xs">
                                Preencha os dados e adicione ingredientes para visualizar a tabela ANVISA.
                            </div>
                        )}
                    </CardContent>

                    {result && (
                        <div className="p-6 border-t space-y-4">
                            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                                <Button variant="outline" onClick={handleExportPNG} className="w-full">
                                    <Download className="mr-2 h-4 w-4" /> Exportar Tabela
                                </Button>
                                <Button variant="outline" onClick={handleExportExcel} className="w-full">
                                    <Download className="mr-2 h-4 w-4" /> Exportar Excel
                                </Button>
                                <Button onClick={handleSave} disabled={saving} className="w-full">
                                    {saving ? "Salvando..." : (
                                        <>
                                            <Save className="mr-2 h-4 w-4" /> Salvar Projeto
                                        </>
                                    )}
                                </Button>
                            </div>

                            <div className="border p-4 rounded bg-yellow-50 text-yellow-900 text-sm">
                                <div className="font-semibold mb-2">Alertas Frontais (FOP) - Modelo Lupa</div>
                                <ul className="list-disc pl-5 space-y-1">
                                    <li className={result.per100g.sugarAdded >= 15 ? "text-red-600 font-bold" : "text-green-700"}>
                                        Açúcar Adicionado: {result.per100g.sugarAdded.toFixed(1)}g (Alto se ≥ 15g)
                                    </li>
                                    <li className={result.per100g.fatSat >= 6 ? "text-red-600 font-bold" : "text-green-700"}>
                                        Gordura Saturada: {result.per100g.fatSat.toFixed(1)}g (Alto se ≥ 6g)
                                    </li>
                                    <li className={result.per100g.sodium >= 600 ? "text-red-600 font-bold" : "text-green-700"}>
                                        Sódio: {result.per100g.sodium.toFixed(0)}mg (Alto se ≥ 600mg)
                                    </li>
                                </ul>
                            </div>
                        </div>
                    )}
                </Card>
            </div>
        </div>
    );
}

import { NextAuthOptions } from "next-auth";
import CredentialsProvider from "next-auth/providers/credentials";
import { PrismaClient } from "@prisma/client";
import { compare } from "bcryptjs";

import { prisma } from "@/lib/prisma";

export const authOptions: NextAuthOptions = {
    session: {
        strategy: "jwt",
    },
    pages: {
        signIn: "/login",
        error: "/login",
    },
    providers: [
        CredentialsProvider({
            name: "Sign in",
            credentials: {
                email: { label: "Email", type: "email" },
                password: { label: "Password", type: "password" },
            },
            async authorize(credentials) {
                if (!credentials?.email || !credentials.password) {
                    return null;
                }

                const user = await prisma.user.findUnique({
                    where: {
                        email: credentials.email,
                    },
                });

                if (!user) {
                    return null;
                }

                const isPasswordValid = await compare(
                    credentials.password,
                    user.password
                );

                if (!isPasswordValid) {
                    return null;
                }

                return {
                    id: user.id + "",
                    email: user.email,
                    name: user.name,
                };
            },
        }),
    ],
    callbacks: {
        async session({ session, token }) {
            return {
                ...session,
                user: {
                    ...session.user,
                    id: token.id,
                },
            };
        },
        async jwt({ token, user }) {
            if (user) {
                return {
                    ...token,
                    id: user.id,
                };
            }
            return token;
        },
    },
};

